function resolveErrorBasePath(validationError: RawValidationError): string {
  const rawPath = validationError.instancePath ?? validationError.dataPath;
  if (!rawPath) {
    return '';
  }
  const normalizedSegments = rawPath.replaceAll(/\['([^']+)'\]|\["([^"]+)"\]|\[(\d+)\]/g, '.$1$2$3');
  return normalizedSegments.replace(/^[/.]/, '').replaceAll('/', '.');
}

